import random
class LFUApprox:
    def __init__(self, maxkeys):
        self.data = {}
        self.freq = {}
        self.maxkeys = maxkeys
    def put(self, k):
        if k in self.data:
            self.freq[k] += 1
            return
        if len(self.data) >= self.maxkeys:
            sample = random.sample(list(self.data.keys()), min(5, len(self.data)))
            victim = min(sample, key=lambda x: self.freq[x])
            del self.data[victim]; del self.freq[victim]
            print(f"    淘汰低频 {victim}")
        self.data[k] = 1
        self.freq[k] = 1

random.seed(2)
c = LFUApprox(maxkeys=3)
for k in ["a", "b", "c"]:
    c.put(k)
for _ in range(5):
    c.freq["a"] += 1  # a 高频
print("近似 LFU 淘汰 (allkeys-lfu):")
print("  访问频率 a=6 b=1 c=1")
c.put("d")
c.put("e")
print("  最终 key:", sorted(c.data.keys()))
print("  LFU 用对数计数器+衰减, 近似统计访问频次, 防缓存污染优于 LRU")
